import {fmtFull,fmtTime} from '../engine.js?v=3';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function setupSourceData(getState){
 if(!document.querySelector('[data-view-source]'))return;
 const dialog=document.createElement('dialog');dialog.className='source-data-dialog';dialog.setAttribute('aria-labelledby','source-data-title');document.body.append(dialog);
 let kind='charts',patientId=null,opener=null;
 const field=(label,value)=>`<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`;
 function render(){
  const patients=getState().cases,c=patients.find(p=>p.id===patientId)||patients[0];patientId=c.id;
  const completed=c.sourceStatus==='completed',a=c.appointment;
  dialog.innerHTML=`<div class="source-data-heading"><div><h2 id="source-data-title">${kind==='charts'?'Patient charts':'Treatment history'}</h2><p>Source data used for response context</p></div><button type="button" class="calendar-close" data-close-source aria-label="Close source data">×</button></div><div class="source-data-layout"><nav class="source-patient-list" aria-label="Source patients">${patients.map(p=>`<button type="button" data-source-patient="${esc(p.id)}" aria-pressed="${p.id===patientId}"><strong>${esc(p.name)}</strong></button>`).join('')}</nav><div class="source-patient-info"><div class="source-patient-heading"><strong>${esc(c.name)}</strong></div>${kind==='charts'?`<section class="source-data-section"><h3>Chart record</h3><dl>${field('Patient',c.name)}${field('Recommended care',c.treatment)}${field('Text contact',c.contact?'Allowed':'Stopped by patient')}</dl><h3>Clinical note</h3><blockquote>${esc(c.note||'No clinical note available.')}</blockquote></section>`:`<section class="source-data-section"><h3>Recorded treatment</h3><dl>${field('Treatment',c.treatment)}${field('Completion',completed?'Completion recorded':'No completion recorded')}${field('Care plan',completed?'Complete':c.sourceStatus==='active'?'Outstanding recommendation':c.sourceStatus||'Not recorded')}</dl><h3>Associated appointment</h3>${a?`<dl>${field('Visit type',a.kind)}${field('When',`${fmtFull(a.start)} · ${fmtTime(a.start)}`)}${field('Provider',a.provider)}${field('Duration',`${a.duration} minutes`)}</dl><p class="source-data-note">An appointment record does not by itself confirm that treatment was completed.</p>`:'<p class="source-data-note">No appointment recorded for this treatment.</p>'}</section>`}</div></div><div class="source-data-footer">Read only · fictional source records. This shows the data available to the prototype, not a live AI request.</div>`;
 }
 document.addEventListener('click',event=>{const button=event.target.closest('[data-view-source]');if(!button)return;kind=button.dataset.viewSource;patientId=getState().selected;opener=button;render();dialog.showModal();dialog.querySelector('[data-source-patient][aria-pressed="true"]')?.scrollIntoView({block:'nearest',inline:'nearest'});});
 dialog.addEventListener('click',event=>{if(event.target.closest('[data-close-source]')){dialog.close();return;}const button=event.target.closest('[data-source-patient]');if(button){const scroll=dialog.querySelector('.source-patient-list').scrollTop;patientId=button.dataset.sourcePatient;render();dialog.querySelector('.source-patient-list').scrollTop=scroll;dialog.querySelector(`[data-source-patient="${CSS.escape(patientId)}"]`).focus({preventScroll:true});}});
 let outsideStart=false;const outside=e=>{const r=dialog.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom;};
 dialog.addEventListener('pointerdown',e=>{outsideStart=e.target===dialog&&outside(e);});dialog.addEventListener('pointerup',e=>{if(outsideStart&&e.target===dialog&&outside(e))dialog.close();outsideStart=false;});dialog.addEventListener('close',()=>opener?.focus());
}
